INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnen alle Multicast-Adressen mit FF00::?', 2, '[{"text": "Ja", "correct": true, "because": "IPv6-Multicast-Präfix"}, {"text": "Nein", "correct": false, "because": "FF00::/8 ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element definiert die Reichweite einer Multicast-Adresse?', 3, '[{"text": "Scope", "correct": true, "because": "Begrenzt Verbreitung"}, {"text": "Flags", "correct": false, "because": "Definiert Typ"}, {"text": "Gruppen-ID", "correct": false, "because": "Identifiziert Gruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Multicast-Adresse?', 5, '[{"text": "FF00::/8 Präfix", "correct": true, "because": "Kennzeichnet Multicast"}, {"text": "Scope-Feld", "correct": true, "because": "Definiert Reichweite"}, {"text": "Portnummer", "correct": false, "because": "Transportebene"}, {"text": "Checksumme", "correct": false, "because": "Nicht im Header"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::1 ist link-lokal. b) Scope ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scope ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Multicast-Adressen?', 4, '[{"text": "Scope-Wert", "correct": false, "because": "Bestimmt Reichweite"}, {"text": "FF00:: Präfix", "correct": false, "because": "Multicast-Kennung"}, {"text": "Einzelne MAC-Adresse", "correct": true, "because": "Gruppenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FF00::1 eine gültige Adresse ist?', 2, '[{"text": "Nein", "correct": true, "because": "Scope und Gruppe fehlen"}, {"text": "Ja", "correct": false, "because": "Ungenau definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Scope-Wert steht für link-lokal?', 3, '[{"text": "2", "correct": true, "because": "FF02:: für link-lokal"}, {"text": "5", "correct": false, "because": "Site-lokal"}, {"text": "E", "correct": false, "because": "Global"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile hat eine Multicast-Adresse?', 5, '[{"text": "Präfix FF00::/8", "correct": true, "because": "Multicast-Kennung"}, {"text": "Scope", "correct": true, "because": "Reichweite definiert"}, {"text": "Source-Adresse", "correct": false, "because": "Nicht enthalten"}, {"text": "Hop-Limit", "correct": false, "because": "Header-Feld"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) FF00::/8 ist für Multicast. b) Scope ist immer global. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Scope variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Multicast-Adresse?', 4, '[{"text": "Scope", "correct": false, "because": "Definiert Reichweite"}, {"text": "Gruppen-ID", "correct": false, "because": "Identifiziert Empfänger"}, {"text": "DNS-Name", "correct": true, "because": "Nicht Adressbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF05::1 link-lokal?', 2, '[{"text": "Nein", "correct": true, "because": "Site-lokal, Scope 5"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit FF02"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich für alle Geräte im lokalen Segment?', 4, '[{"text": "FF02::1", "correct": true, "because": "Link-lokal, alle Knoten"}, {"text": "FF0E::1", "correct": false, "because": "Globaler Scope"}, {"text": "FE80::1", "correct": false, "because": "Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast-Adressen nur lokal sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Scope kann global sein"}, {"text": "Ja", "correct": false, "because": "Reichweite variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Multicast-Adressen?', 3, '[{"text": "Korrekter Scope", "correct": true, "because": "Bestimmt Zielbereich"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Schnelle Antwort", "correct": false, "because": "Diagnoseabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FF02::2 erreicht alle Router. b) Scope ist 4 Bit lang.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Router und 4-Bit-Scope"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Multicast-Adressen?', 5, '[{"text": "Effiziente Gruppenkommunikation", "correct": true, "because": "Weniger Pakete"}, {"text": "Flexible Reichweite", "correct": true, "because": "Scope steuerbar"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Multicast-Adressen unwichtig?', 3, '[{"text": "FF00::/8", "correct": false, "because": "Multicast-Kennung"}, {"text": "Scope", "correct": false, "because": "Definiert Reichweite"}, {"text": "Einzel-IP", "correct": true, "because": "Gruppenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist FF08::1 eine globale Adresse?', 3, '[{"text": "Nein", "correct": true, "because": "Organisation-lokal, Scope 8"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit FF0E"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Scope die Gruppen-ID beeinflusst?', 2, '[{"text": "Nein", "correct": true, "because": "Unabhängige Felder"}, {"text": "Ja", "correct": false, "because": "Scope definiert nur Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für eine site-lokale Gruppe?', 4, '[{"text": "FF05::2", "correct": true, "because": "Site-lokal, alle Router"}, {"text": "FF02::2", "correct": false, "because": "Link-lokal"}, {"text": "FF0E::2", "correct": false, "because": "Global"}]');
